let tutorialBusy=false,tutorialError='',tutorialPaintKey='',tutorialSchedule=0,tutorialSavedUndo=null;
const tutorialSession=()=>state.tutorial?.version===TutorialCore.VERSION?state.tutorial:null;
const tutorialPractice=()=>!!B()?.tutorialSessionId;
function tutorialAssert(){const t=tutorialSession();if(!t||!TutorialCore.ownedBoard(state,t))throw new Error('请先创建或继续练习画板。');if(state.activeBoard!==t.boardId)throw new Error('先返回练习画板，原项目不会被教程修改。');return t}
function tutorialCommand(n,a){const r=dispatch(n,a);if(!r.ok)throw new Error(r.msg);return r}
function tutorialCloseAux(){closePan();$('#guide').classList.remove('o');if(utility.classList.contains('o')){utility.classList.remove('o');utilityKind=null}if(modelConnect.open)mcClose();if(skillbook.open)skillbook.close()}
function tutorialRemember(){return{boardId:state.activeBoard,room:state.room,sel:state.sel,tool,detOpen,prevView:prevView?{...prevView}:null}}
function tutorialOpenHome(){const t=tutorialSession();tutorialHome.innerHTML=tutorialHomeMarkup({mode:t?.status==='complete'?'complete':t?'resume':'welcome',title:t?TutorialCore.steps[t.step][1]:'假装运营一次自媒体',step:(t?.step||0)+1,total:TutorialCore.steps.length,chapters:TutorialCore.chapters,hasSession:!!t,canResume:!!t&&TutorialCore.ownedBoard(state,t),completed:t?.completed.length||0,checklist:['组织团队、明确任务与材料','停止与继续，保留已有输出','连接多个项目、按白名单共享','人工审核、模拟发布与数据复盘','查看近况、删除、撤销、重做与恢复','建立项目组、看组内进度、解散与恢复'],shortcuts:TutorialCore.shortcuts});if(!tutorialHome.open)tutorialHome.showModal()}
